window.DV_TOPICS=window.DV_TOPICS||{};window.DV_TOPICS["rent-by-district"]={"id":"rent-by-district","order":12,"title_en":"Rent by District","title_zh":"分区房租","blurb_zh":"各区租金与六年涨幅","scene_zh":"八个城区的一居室挂牌价（模拟）","views":[{"id":"rent","type":"bar","label_zh":"月租","label_en":"Monthly rent","subject":"One-bedroom rent","subtitle_en":"Median one-bedroom rent by district.","unit":{"en":"yuan per month","short":"¥","decimals":0,"kind":"count"},"data":{"x":{"label_en":"District","label_zh":"城区","values":["Riverside","Old Town","University","Tech Park","Lakeside","North Gate","Harbor","West Field"]},"series":[{"id":"rent","name_en":"Monthly rent","name_zh":"月租","slot":1,"values":[7800,6400,5600,5200,4900,4300,3900,3500]}]},"features":[{"kind":"highest","marks":["bar:rent:0"],"slots":{"subject":"One-bedroom rent","unit":"¥","category":"Riverside","period":"","series_name":"Monthly rent","value":"7,800 yuan per month","rank":"1","gap":"0 yuan per month","top_category":"Riverside","top_value":"7,800 yuan per month"},"auto":false,"id":"rb-high","examples":[{"en":"Riverside is the most expensive district, at 7,800 yuan a month.","zh":"滨江区最贵，月租 7800 元。"}],"note_zh":"the most expensive / the highest rent；价格高用 expensive 比 high 自然。","interpret_zh":"挂牌价不等于成交价，也不代表所有户型。"},{"kind":"ranking","marks":["bar:rent:1"],"slots":{"subject":"One-bedroom rent","unit":"¥","category":"Old Town","period":"","series_name":"Monthly rent","value":"6,400 yuan per month","rank":"2","gap":"1,400 yuan per month","top_category":"Riverside","top_value":"7,800 yuan per month"},"auto":false,"id":"rb-rank","examples":[{"en":"Old Town ranks second, at 6,400 yuan.","zh":"老城区排第二，月租 6400 元。"}],"note_zh":"rank + 序数词，不加 the；也可以说 come second。","interpret_zh":"排名只说明相对位置，差距大小还要看具体数字。"},{"kind":"small_gap","marks":["bar:rent:2"],"slots":{"subject":"One-bedroom rent","unit":"¥","category":"University","period":"","series_name":"Monthly rent","value":"5,600 yuan per month","rank":"3","gap":"2,200 yuan per month","top_category":"Riverside","top_value":"7,800 yuan per month"},"auto":false,"id":"rb-small","examples":[{"en":"University and Tech Park are close: 5,600 versus 5,200 yuan.","zh":"大学城和科技园很接近：5600 对 5200 元。"}],"note_zh":"versus / compared with 用来点出两个接近的数值。","interpret_zh":"400 元的差距在这组数据里算小，但换到别的城市可能不小。"},{"kind":"compare_groups","marks":["bar:rent:3"],"slots":{"subject":"One-bedroom rent","unit":"¥","category":"Tech Park","period":"","series_name":"Monthly rent","value":"5,200 yuan per month","rank":"4","gap":"2,600 yuan per month","top_category":"Riverside","top_value":"7,800 yuan per month"},"auto":false,"id":"rb-groups","examples":[{"en":"The four inner districts average 6,250 yuan, well above the outer four at 4,150.","zh":"内圈四区平均 6250 元，明显高于外圈四区的 4150 元。"}],"note_zh":"average + 数值，well above / well below 表示差距明显。","interpret_zh":"把八个区硬分成两组是为了说明结构，分组线本身是人为的。"},{"kind":"ranking","marks":["bar:rent:4"],"slots":{"subject":"One-bedroom rent","unit":"¥","category":"Lakeside","period":"","series_name":"Monthly rent","value":"4,900 yuan per month","rank":"5","gap":"2,900 yuan per month","top_category":"Riverside","top_value":"7,800 yuan per month"},"auto":true},{"kind":"ranking","marks":["bar:rent:5"],"slots":{"subject":"One-bedroom rent","unit":"¥","category":"North Gate","period":"","series_name":"Monthly rent","value":"4,300 yuan per month","rank":"6","gap":"3,500 yuan per month","top_category":"Riverside","top_value":"7,800 yuan per month"},"auto":true},{"kind":"item","marks":["bar:rent:6"],"slots":{"subject":"One-bedroom rent","unit":"¥","category":"Harbor","period":"","series_name":"Monthly rent","value":"3,900 yuan per month","rank":"7","gap":"3,900 yuan per month","top_category":"Riverside","top_value":"7,800 yuan per month"},"auto":false,"id":"rb-item","examples":[{"en":"Harbor sits near the bottom, at 3,900 yuan a month.","zh":"港区接近最低，月租 3900 元。"}],"note_zh":"sit near the bottom / at the lower end 描述中下位置。","interpret_zh":"接近最低不等于最低，描述时不要用 the lowest。"},{"kind":"lowest","marks":["bar:rent:7"],"slots":{"subject":"One-bedroom rent","unit":"¥","category":"West Field","period":"","series_name":"Monthly rent","value":"3,500 yuan per month","rank":"8","gap":"4,300 yuan per month","top_category":"Riverside","top_value":"7,800 yuan per month"},"auto":false,"id":"rb-low","examples":[{"en":"West Field has the lowest rent, at 3,500 yuan.","zh":"西田租金最低，为 3500 元。"}],"note_zh":"the lowest rent / the cheapest district；注意主语不同。","interpret_zh":"最低价可能反映通勤距离，而不是房子本身更差。"}],"overview_zh":"八个区的租金从 7800 元递减到 3500 元，内圈明显高于外圈。这张图只比较挂牌价，不说明成交价、户型或通勤时间。","descriptions":{"general":{"a2":"Riverside is the most expensive district, at 7,800 yuan a month. West Field is the cheapest, at 3,500 yuan. The other districts fall in between.","b1":"Rent ranges from 7,800 yuan in Riverside to 3,500 yuan in West Field. The four inner districts are clearly more expensive than the outer four, with averages of 6,250 and 4,150 yuan.","b2":"Monthly rent forms a clear gradient from the city center outward, falling from 7,800 yuan in Riverside to 3,500 yuan in West Field. The sharpest drop comes between Riverside and Old Town, while University and Tech Park are separated by only 400 yuan."},"ielts":"One-bedroom rent was highest in Riverside at 7,800 yuan per month and lowest in West Field at 3,500 yuan. The four central districts averaged 6,250 yuan, compared with 4,150 yuan in the outer districts.","business":"Rent declines steadily from the center outward. Riverside commands a 123 percent premium over West Field, while University and Tech Park are effectively the same price — a useful signal for where to target renters."}},{"id":"change","type":"bar","label_zh":"六年涨幅","label_en":"Change since 2020","subject":"Rent growth since 2020","subtitle_en":"Change in one-bedroom rent, 2020 to 2026.","unit":{"en":"percent","short":"%","decimals":0,"kind":"percent"},"data":{"x":{"label_en":"District","label_zh":"城区","values":["Riverside","Old Town","University","Tech Park","Lakeside","North Gate","Harbor","West Field"]},"series":[{"id":"growth","name_en":"Rent change","name_zh":"涨幅","slot":1,"values":[28,9,22,35,14,-6,3,-11]}]},"features":[{"kind":"ranking","marks":["bar:growth:0"],"slots":{"subject":"Rent growth since 2020","unit":"%","category":"Riverside","period":"","series_name":"Rent change","value":"28 percent","rank":"2","gap":"7 percent","top_category":"Tech Park","top_value":"35 percent"},"auto":true},{"kind":"compare_groups","marks":["bar:growth:1"],"slots":{"subject":"Rent growth since 2020","unit":"%","category":"Old Town","period":"","series_name":"Rent change","value":"9 percent","rank":"5","gap":"26 percent","top_category":"Tech Park","top_value":"35 percent"},"auto":false,"id":"rbc-compare","examples":[{"en":"Old Town has the second-highest rent but only the sixth-fastest growth, at 9 percent.","zh":"老城区租金第二高，但涨幅只排第六，为 9%。"}],"note_zh":"but 连接两个相反的事实；only 强调低于预期。","interpret_zh":"高租金加低增长，说明这个区的租金已经比较稳定。"},{"kind":"ranking","marks":["bar:growth:2"],"slots":{"subject":"Rent growth since 2020","unit":"%","category":"University","period":"","series_name":"Rent change","value":"22 percent","rank":"3","gap":"13 percent","top_category":"Tech Park","top_value":"35 percent"},"auto":false,"id":"rbc-rank","examples":[{"en":"University ranks second for growth, at 22 percent.","zh":"大学城涨幅排第二，为 22%。"}],"note_zh":"rank second for growth；如果要强调方面，用 in terms of。","interpret_zh":"涨幅排名和租金排名不是一回事。"},{"kind":"highest","marks":["bar:growth:3"],"slots":{"subject":"Rent growth since 2020","unit":"%","category":"Tech Park","period":"","series_name":"Rent change","value":"35 percent","rank":"1","gap":"0 percent","top_category":"Tech Park","top_value":"35 percent"},"auto":false,"id":"rbc-high","examples":[{"en":"Tech Park saw the fastest growth, with rents up 35 percent.","zh":"科技园涨得最快，租金上涨 35%。"}],"note_zh":"see + 变化 是书面描述数据变化的常用动词：saw the fastest growth。","interpret_zh":"涨得最快不等于租金最高：科技园的绝对租金只排第四。"},{"kind":"ranking","marks":["bar:growth:4"],"slots":{"subject":"Rent growth since 2020","unit":"%","category":"Lakeside","period":"","series_name":"Rent change","value":"14 percent","rank":"4","gap":"21 percent","top_category":"Tech Park","top_value":"35 percent"},"auto":true},{"kind":"item","marks":["bar:growth:5"],"slots":{"subject":"Rent growth since 2020","unit":"%","category":"North Gate","period":"","series_name":"Rent change","value":"-6 percent","rank":"7","gap":"41 percent","top_category":"Tech Park","top_value":"35 percent"},"auto":false,"id":"rbc-negative","examples":[{"en":"North Gate was one of two districts where rent fell, down 6 percent.","zh":"北门是两个租金下跌的区之一，下降了 6%。"}],"note_zh":"where rent fell 是定语从句；down 6 percent 是简写。","interpret_zh":"负增长说明租金回落，但不代表房子更便宜到可负担。"},{"kind":"item","marks":["bar:growth:6"],"slots":{"subject":"Rent growth since 2020","unit":"%","category":"Harbor","period":"","series_name":"Rent change","value":"3 percent","rank":"6","gap":"32 percent","top_category":"Tech Park","top_value":"35 percent"},"auto":false,"id":"rbc-item","examples":[{"en":"Harbor barely moved, with growth of just 3 percent.","zh":"港区几乎没动，只涨了 3%。"}],"note_zh":"barely moved 比 grew slowly 更像母语者的说法。","interpret_zh":"接近零增长时，说“持平”比说“上涨”更准确。"},{"kind":"lowest","marks":["bar:growth:7"],"slots":{"subject":"Rent growth since 2020","unit":"%","category":"West Field","period":"","series_name":"Rent change","value":"-11 percent","rank":"8","gap":"46 percent","top_category":"Tech Park","top_value":"35 percent"},"auto":false,"id":"rbc-low","examples":[{"en":"West Field had the weakest performance, with rent down 11 percent.","zh":"西田表现最弱，租金下降 11%。"}],"note_zh":"the weakest performance 是商业/雅思都常见的评价说法。","interpret_zh":"跌幅最大可能是因为基数或供给变化，图里没有解释。"}],"overview_zh":"涨幅和租金水平并不同步：科技园涨得最快但租金只排第四，老城区租金第二高却只涨了 9%。有两个区出现负增长。","descriptions":{"general":{"a2":"Rents rose in most districts. Tech Park grew the most, by 35 percent, while West Field and North Gate became cheaper.","b1":"Tech Park saw the fastest rent growth at 35 percent, followed by Riverside and University. Two districts, North Gate and West Field, recorded small declines.","b2":"Rent growth varied widely across districts, from a 35 percent rise in Tech Park to an 11 percent fall in West Field. The ranking by growth is quite different from the ranking by rent level: Old Town has the second-highest rent but only the sixth-fastest growth."},"ielts":"Rents increased in six of the eight districts, with Tech Park recording the largest rise at 35 percent. By contrast, West Field and North Gate saw declines of 11 and 6 percent respectively.","business":"Growth is concentrated in Tech Park and University, where demand is outpacing supply. Old Town's high rent and slow growth suggest a mature market; the two falling districts are where affordability pressure is easing."}}]};
